  },
  {
    "statement": "IF tool_name = \"analyze_pool_quality\" AND call is allowed THEN post‑condition: analysis_done = true ∧ analysis_episode_id = episode_id."
  },
  {
    "statement": "IF tool_name = \"run_stress_test\" AND call is allowed THEN post‑condition: stress_test_done = true ∧ stress_test_episode_id = episode_id."
  },
  {
    "statement": "IF tool_name = \"assign_rating\" AND call is allowed THEN post‑condition: rating is recorded, stress_test_passed = true, and no further high‑risk tools may be invoked in the same episode."
  }
]
